import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`business-consultant`,heroTitle:`Consultant-grade strategy work, done for you`,heroSubtitle:`Perplexity Computer analyzes your business, builds your strategy, and drafts your plan — automatically.`,inputUrlCta:`Analyze my business`,inputUrlPlaceholder:`your website`,inputUrlPrefill:`Go to {url} and act as a business consultant. 1) Analyze the business model, offer, customers, pricing, positioning, website funnel, competitors, and growth constraints. 2) Identify the strongest opportunities across acquisition, retention, operations, service packaging, and partnerships. 3) Build a practical growth strategy with priorities, tradeoffs, risks, and success metrics. 4) Draft a business plan and model summary with revenue levers, customer segments, operating assumptions, and next actions. 5) Prepare a concise executive brief that can be shared in Notion, Google Sheets, Slack, HubSpot, or Salesforce.`,heroOverlaySteps:[`Analyzing your offer, customers, positioning, and business model`,`Comparing competitors, growth constraints, and market opportunities`,`Building strategy priorities, risks, metrics, and next actions`,`Business plan and model summary ready to review`],generatingSteps:[`Opening {url} to understand your business, customers, and positioning`,`Designing an agent to analyze the market, funnel, competitors, and model`,`Configuring growth strategy, operating assumptions, and success metrics`,`Preparing a consultant-style plan with priorities, risks, and next actions`],featureSectionTitle:`From business snapshot to strategy plan`,featureCardTitles:[`Connects to your business stack`,`Outputs your team can use`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Slack, HubSpot, Salesforce — Computer keeps analysis, planning, pipeline, and operating notes in the tools you already use.`,`Business analysis. Growth strategy. Business plan. Revenue model. Priority roadmap. Computer gives you consultant-grade work without the slide churn.`],capabilitySectionTitle:`Your business consultant, on autopilot`,capabilitySectionSubtitle:`Share your website, step away, and come back to strategy work your team can evaluate.`,capabilityCards:[{title:`Business Analysis`,description:`Computer can analyze your offer, customers, funnel, pricing, operations, and competitors to find the levers that matter.`},{title:`Growth Strategy`,description:`Computer can turn market and funnel findings into prioritized growth plays with tradeoffs, metrics, and risks.`},{title:`Business Plan & Model`,description:`Computer can draft a business plan and model summary covering segments, revenue levers, assumptions, and next actions.`},{title:`Connect Your Tools`,description:`Computer can organize strategy work across Google Sheets, Notion, Slack, HubSpot, and Salesforce so execution stays connected.`},{title:`Remember & Learn`,description:`Computer can remember your business model, customer segments, preferred metrics, and past strategy decisions across sessions.`},{title:`Monitor & Alert`,description:`Computer can monitor competitors, pipeline changes, reviews, and growth metrics, then alert you when the plan needs attention.`}]});export{t as default};
